"use strict";(self.webpackChunkdoc_adk_training_site=self.webpackChunkdoc_adk_training_site||[]).push([[2726],{3872:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>i,metadata:()=>r,toc:()=>c});const r=JSON.parse('{"id":"module28-building-mcp-tools/lab-solution","title":"Lab Solution","description":"Goal","source":"@site/../training/module28-building-mcp-tools/lab-solution.md","sourceDirName":"module28-building-mcp-tools","slug":"/module28-building-mcp-tools/lab-solution","permalink":"/doc-adk-training/docs/module28-building-mcp-tools/lab-solution","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Lab Solution"}}');var s=t(4848),o=t(8453);const i={sidebar_position:3,title:"Lab Solution"},a='Lab 28 Solution: Building a "Shopping Cart" MCP Server',l={},c=[{value:"Goal",id:"goal",level:2},{value:"<code>custom_mcp_server/cart_server.py</code>",id:"custom_mcp_servercart_serverpy",level:3},{value:"<code>custom_mcp_server/agent.py</code>",id:"custom_mcp_serveragentpy",level:3},{value:"Self-Reflection Answers",id:"self-reflection-answers",level:3}];function p(e){const n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"lab-28-solution-building-a-shopping-cart-mcp-server",children:'Lab 28 Solution: Building a "Shopping Cart" MCP Server'})}),"\n",(0,s.jsx)(n.h2,{id:"goal",children:"Goal"}),"\n",(0,s.jsxs)(n.p,{children:["This file contains the complete code for both the ",(0,s.jsx)(n.code,{children:"cart_server.py"})," and the ",(0,s.jsx)(n.code,{children:"agent.py"})," client script for the Shopping Cart MCP lab."]}),"\n",(0,s.jsx)(n.h3,{id:"custom_mcp_servercart_serverpy",children:(0,s.jsx)(n.code,{children:"custom_mcp_server/cart_server.py"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'# Filename: cart_server.py\nimport asyncio\nimport json\nfrom mcp import types as mcp_types\nfrom mcp.server.lowlevel import Server, NotificationOptions\nfrom mcp.server.models import InitializationOptions\nimport mcp.server.stdio\n\n# --- Server State ---\n# In a real application, this would be a database. For this lab, a simple\n# in-memory list is enough to demonstrate statefulness.\nCART = []\n\n# --- MCP Server Setup ---\napp = Server("shopping_cart_mcp_server")\n\n@app.list_tools()\nasync def list_mcp_tools() -> list[mcp_types.Tool]:\n    """Defines the \'menu\' of tools our server offers."""\n    print("[Server]: Client asked for the list of tools.")\n    \n    add_item_tool = mcp_types.Tool(\n        name="add_item_to_cart",\n        description="Adds a single item to the user\'s shopping cart.",\n        inputSchema={\n            "type": "object",\n            "properties": {\n                "item": {"type": "string", "description": "The item to add to the cart."}\n            },\n            "required": ["item"],\n        },\n    )\n    \n    view_cart_tool = mcp_types.Tool(\n        name="view_cart",\n        description="Shows all the items currently in the user\'s shopping cart.",\n        inputSchema={"type": "object", "properties": {}}, # No arguments needed\n    )\n    \n    return [add_item_tool, view_cart_tool]\n\n@app.call_tool()\nasync def call_mcp_tool(name: str, arguments: dict) -> list[mcp_types.Content]:\n    """Handles the execution of our tools."""\n    print(f"[Server]: Client called tool \'{name}\'.")\n\n    # --- Tool Logic ---\n    if name == "add_item_to_cart":\n        item = arguments.get("item")\n        if item:\n            CART.append(item)\n            response_text = json.dumps({"status": "success", "message": f"Added \'{item}\' to the cart."}) \n        else:\n            response_text = json.dumps({"status": "error", "message": "No item provided."})\n        \n        return [mcp_types.TextContent(type="text", text=response_text)]\n\n    elif name == "view_cart":\n        response_text = json.dumps({"status": "success", "cart": CART})\n        return [mcp_types.TextContent(type="text", text=response_text)]\n\n    else:\n        response_text = json.dumps({"status": "error", "message": f"Tool \'{name}\' not found."}) \n        return [mcp_types.TextContent(type="text", text=response_text)]\n\n# --- MCP Server Runner ---\nasync def run_mcp_stdio_server():\n    """Runs the server, listening for connections over standard input/output."""\n    async with mcp.server.stdio.stdio_server() as (read_stream, write_stream):\n        print("[Server]: Waiting for a client to connect...")\n        await app.run(\n            read_stream,\n            write_stream,\n            InitializationOptions(\n                server_name=app.name,\n                server_version="0.1.0",\n                capabilities=app.get_capabilities(NotificationOptions(), {}),\n            ),\n        )\n        print("[Server]: Client disconnected.")\n\nif __name__ == "__main__":\n    print("[Server]: Starting Shopping Cart MCP Server...")\n    try:\n        asyncio.run(run_mcp_stdio_server())\n    except KeyboardInterrupt:\n        print("\\n[Server]: Shutting down.")\n'})}),"\n",(0,s.jsx)(n.h3,{id:"custom_mcp_serveragentpy",children:(0,s.jsx)(n.code,{children:"custom_mcp_server/agent.py"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"# Filename: agent.py\nimport pathlib\nfrom google.adk import Agent\nfrom google.adk.tools.mcp_tool.mcp_toolset import McpToolset\nfrom google.adk.tools.mcp_tool.mcp_session_manager import StdioConnectionParams\nfrom mcp import StdioServerParameters\n\n# Get the absolute path to our server script, based on this file's own\n# location rather than the process's working directory \u2014 'adk web'/'adk run'\n# are launched from the parent directory, so a relative path would break.\nPATH_TO_SERVER = str(pathlib.Path(__file__).parent / \"cart_server.py\")\n\nroot_agent = Agent(\n    model='gemini-3.5-flash',\n    name='shopping_agent',\n    instruction='You are a shopping assistant. Help the user by adding items to their cart and showing them their cart contents.',\n    tools=[\n        McpToolset(\n            connection_params=StdioConnectionParams(\n                server_params=StdioServerParameters(\n                    command='python3',\n                    args=[PATH_TO_SERVER],\n                ),\n            ),\n        )\n    ],\n)\n"})}),"\n",(0,s.jsx)(n.h3,{id:"self-reflection-answers",children:"Self-Reflection Answers"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsxs)(n.strong,{children:["In our ",(0,s.jsx)(n.code,{children:"cart_server.py"}),", we used a global list ",(0,s.jsx)(n.code,{children:"CART"})," to store the state. Why is this approach not suitable for a production environment?"]})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Answer:"})," Multiple server instances would each have their own independent copy of the list, leading to inconsistent state, and every client would share the exact same cart. A better solution is an external, centralized store like Redis or Firestore, keyed per user or session."]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsxs)(n.strong,{children:["The server declares ",(0,s.jsx)(n.code,{children:"capabilities"})," in its ",(0,s.jsx)(n.code,{children:"InitializationOptions"}),". What role does capability negotiation play in the MCP handshake?"]})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Answer:"})," During initialization, the client and server exchange the features they support (e.g. tools, prompts, resources, notifications). ",(0,s.jsx)(n.code,{children:"app.get_capabilities(...)"})," tells the client exactly what this server offers. If a client later expects a capability the server never declared, the request fails cleanly during negotiation instead of the server behaving unpredictably mid-conversation."]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"What are the benefits of decoupling the tool logic from the agent?"})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Answer:"})," Independent scalability, modular maintenance, and cross-client reusability. Any MCP-compliant application can now use your shopping cart, not just ADK agents."]}),"\n"]}),"\n"]}),"\n"]})]})}function d(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(p,{...e})}):p(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>i,x:()=>a});var r=t(6540);const s={},o=r.createContext(s);function i(e){const n=r.useContext(o);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),r.createElement(o.Provider,{value:n},e.children)}}}]);